export async function mountOilScene(canvas){
 const T=await import('./three.module.js');
 const renderer=new T.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<701?1.25:1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(34,1,.1,60);
 const ec=document.createElement('canvas');ec.width=1024;ec.height=512;const c=ec.getContext('2d');c.fillStyle='#554431';c.fillRect(0,0,1024,512);c.fillStyle='#fff4df';c.fillRect(40,0,180,510);c.fillStyle='#ffffff';c.fillRect(700,20,100,470);c.fillStyle='#b38843';c.fillRect(450,240,150,180);const env=new T.CanvasTexture(ec);env.mapping=T.EquirectangularReflectionMapping;const pm=new T.PMREMGenerator(renderer);scene.environment=pm.fromEquirectangular(env).texture;pm.dispose();env.dispose();scene.add(new T.HemisphereLight(0xffffff,0xb49453,1.4));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-3,4,5);scene.add(light);
 const gold=new T.MeshPhysicalMaterial({color:0xc98b18,metalness:.22,roughness:.1,clearcoat:1,clearcoatRoughness:.06,transmission:.38,thickness:1.3,ior:1.47,transparent:true});
 const outline=[[0,-1.1],[.26,-1.04],[.53,-.83],[.69,-.48],[.72,-.18],[.65,.17],[.5,.49],[.31,.86],[.14,1.23],[.025,1.61],[0,1.74]];
 const drop=new T.Mesh(new T.LatheGeometry(outline.map(([r,y])=>new T.Vector2(r,y)),96),gold);scene.add(drop);
 const particles=new T.InstancedMesh(new T.SphereGeometry(1,10,8),new T.MeshStandardMaterial({color:0xc89b40,metalness:.7,roughness:.22,transparent:true,opacity:.6}),160);scene.add(particles);
 const field=new T.Group();scene.add(field);field.add(particles);const dummy=new T.Object3D(),seeds=Array.from({length:160},(_,i)=>({x:Math.sin(i*43.7)*6,y:Math.cos(i*17.13)*4,z:-3-(i%11)*.65,s:.012+(i%4)*.012}));let w=0,h=0;
 const paths=[];for(let j=0;j<7;j++){for(let i=0;i<40;i++){const a=i*.19+j*.9,b=(i+1)*.19+j*.9;paths.push(Math.sin(a)*2.2+(j-3)*.28,(i-20)*.14,Math.cos(a)*1.5-2,Math.sin(b)*2.2+(j-3)*.28,(i+1-20)*.14,Math.cos(b)*1.5-2)}}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(paths,3));const threads=new T.LineSegments(geometry,new T.LineBasicMaterial({color:0xbb8d26,transparent:true,opacity:0}));field.add(threads);
 return(time,p,mouse)=>{const width=canvas.clientWidth,height=canvas.clientHeight;if(!width||!height)return;if(w!==width||h!==height){w=width;h=height;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}const mobile=width<701;const zoom=Math.max(0,Math.min(1,(p-.08)/.26)),fade=Math.max(0,Math.min(1,(p-.31)/.09));const dive=Math.max(0,Math.min(1,(p-.18)/.16)),roll=Math.max(0,Math.min(1,(p-.09)/.1));camera.position.set(Math.sin(dive*.75)*1.2,Math.sin(dive*.5)*.5,8-zoom*6);camera.lookAt(dive*.8,0,-dive*2);field.rotation.y=dive*1.1;field.rotation.z=dive*-.2;threads.material.opacity=Math.sin(dive*Math.PI*.85)*.28*(1-fade);drop.position.set((mobile?0:1.5)*(1-zoom*.7),mobile?-.65:0,0);drop.rotation.set(-roll*.8+mouse.y*.12,-.3+roll*1.2+mouse.x*.25,-.17+roll*.55);drop.scale.setScalar((mobile?.73:1.12)*(1+zoom*1.9));const dissolve=Math.max(0,Math.min(1,(p-.21)/.08));gold.opacity=1-dissolve;drop.visible=dissolve<1;particles.material.opacity=(.17+zoom*.6)*(1-fade);particles.visible=fade<1;seeds.forEach((s,i)=>{dummy.position.set(s.x*(1+zoom*.5)+mouse.x*.12,s.y+Math.sin(time*.00015+i)*.035,s.z+zoom*5);dummy.scale.setScalar(s.s*(1+zoom));dummy.updateMatrix();particles.setMatrixAt(i,dummy.matrix)});particles.instanceMatrix.needsUpdate=true;renderer.render(scene,camera)};
}
